   "name": "out_of_scope",
   "node_type": "conversation",
   "description": "Question outside the statement debt step",
   "condition": {
    "operator": "matches_intent",
    "description": "The caller asks about something unrelated to their statement debt, the statement e-mail or the statement week, e.g. interest rates, card limit, points or miles, instalments, loans, branch hours, card blocking, changing an address, or another bank transaction. NOT payment, NOT a disputed amount, NOT a request for a person, NOT another person's card, NOT a request for card number digits."
   },
   "on_enter": {
    "type": "tts",
    "text": "Size bu konuda yard\u0131mc\u0131 olam\u0131yorum. Sizi ana men\u00fcye aktarmam\u0131 ister misiniz?"
   },
   "tools": [],
   "task_message": "You asked whether the caller wants to be transferred to the main menu. If the answer is unclear, ask again only: 'Sizi ana men\u00fcye aktarmam\u0131 ister misiniz?'. Do not answer the out-of-scope question and give no figures. Do not call any tool.",
   "extraction_schema": [
    {
     "name": "oos_answer",
     "type": "string",
     "enum_values": [
      "yes",
      "no",
      "none"
     ],
     "description": "Answer to 'Sizi ana men\u00fcye aktarmam\u0131 ister misiniz?' in the caller's LAST message: yes = wants the main menu; no = wants to continue here; none = unclear.",
     "min_confidence": 0.6
    }
   ],
   "max_node_turns": 3,
   "max_turn_transition": "end_tries",
   "excluded_nodes": [
    "out_of_scope",
    "end_main_menu",
    "end_main_menu_transfer",
    "end_no_card",
    "end_no_debt",
    "end_tries",
    "end_service_error",
    "end_week_error",
    "end_agent",
    "end_pay",
    "end_dispute",
    "end_security",
    "end_address",
    "end_silence"
   ],
   "transitions": [
    {
     "target_node": "end_main_menu_transfer",
     "description": "Caller wants the main menu",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "oos_answer",
        "operator": "equals",
        "operand": "yes"
       }
      ]
     }
    },
    {
     "target_node": "__previous__",
     "description": "Caller wants to continue",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "oos_answer",
        "operator": "equals",
        "operand": "no"
       }
      ]
     }
    }
   ]
  }
 },
