   "passthrough_default_transition": "end_service_error",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "config": {
      "timeoutMs": 20000,
      "maxRetries": 1
     },
     "function": {
      "name": "load_cards",
      "handler": "__function__:api_call",
      "description": "cards.list: the customer's eligible credit cards.",
      "parameters": {
       "type": "object",
       "properties": {
        "url": {
         "type": "string",
         "default": "https://yapmak-bank-mock.winter-mountain-4405.workers.dev/voice/v1/cards.list"
        },
        "method": {
         "type": "string",
         "default": "POST"
        },
        "headers": {
         "type": "object",
         "properties": {
          "Content-Type": {
           "type": "string",
           "default": "application/json"
          },
          "Accept": {
           "type": "string",
           "default": "application/json"
          }
         }
        },
        "body": {
         "type": "object",
         "properties": {
          "data": {
           "type": "object",
           "properties": {
            "customerNo": {
             "type": "string",
             "default": "{{customerNumber}}"
            },
            "aiFlow": {
             "type": "string",
             "default": "CardOps"
            }
           }
          },
          "call": {
           "type": "object",
           "properties": {
            "lang": {
             "type": "string",
             "default": "tr"
            }
           }
          }
         },
         "required": [
          "data"
         ]
        }
       }
      }
     },
     "pre_process_code": "try:\n    v = vars.get('customerNumber')\n    if v:\n        config['body'] = dict(data=dict(customerNo=str(v), aiFlow='CardOps'), call=dict(lang='tr'))\nexcept Exception:\n    pass\n"
    }
   ],
   "response_mapping": [
