        "variable": "cards_rc",
        "operator": "equals",
        "operand": "FB_IVR_CHANNEL_102"
       },
       {
        "variable": "load_cards_response.data.result.returnCode",
        "operator": "equals",
        "operand": "FB_IVR_CHANNEL_102"
       },
       {
        "variable": "cards_http",
        "operator": "equals",
        "operand": "404"
       },
       {
        "variable": "load_cards_status_code",
        "operator": "equals",
        "operand": "404"
       }
      ]
     }
    },
    {
     "target_node": "end_service_error",
     "description": "always: service failed",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
  "load_contact": {
