       "properties": {
        "code": {
         "type": "string",
         "default": "import json\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef digits(x):\n    return ''.join(ch for ch in str(x or '') if ch.isdigit())\ndef norm(t):\n    t = str(t or '').replace('I', '\u0131').replace('\u0130', 'i').lower()\n    t = ''.join(ch if (ch.isalnum() or ch.isspace()) else ' ' for ch in t)\n    return ' '.join(t.split())\ndef nm(c):\n    return c.get('name') or ('sonu ' + dg(c.get('last4')) + ' ile biten kart')\ndef join_tr(ns):\n    if len(ns) <= 1:\n        return ''.join(ns)\n    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]\ndef uniq(lst):\n    out = []\n    for c in lst:\n        if nm(c) not in out:\n            out.append(nm(c))\n    return out\nSTOP = ['kart', 'kart\u0131', 'kart\u0131m', 'kart\u0131m\u0131n', 'kart\u0131m\u0131', 'kart\u0131n\u0131', 'kartlar\u0131m', 'olan', 'benim', 'borcu', 'borcunu', 'l\u00fctfen', 'ile', 'biten', 'sonu', 'none', 'null']\ntry:\n    cards = json.loads(s('cards_json') or '[]')\n    elig = [c for c in cards if c.get('main')] or cards\n    said = norm(vars.get('card_name_said'))\n    dd = digits(vars.get('card_digits_said'))\n    intent = s('select_intent')\n    q = s('select_question')\n    toks = [t for t in said.split() if t not in STOP]\n    cand = list(cards)\n    if toks:\n        def tok_ok(c):\n            ct = norm(c.get('name')).split()\n            return all(any(x.startswith(t) or (len(t) >= 4 and t.startswith(x)) for x in ct) for t in toks)\n        cand = [c for c in cand if tok_ok(c)]\n        full = [c for c in cand if norm(c.get('name')) and norm(c.get('name')) in said]\n        if full:\n            m = max(len(norm(c.get('name'))) for c in full)\n            cand = [c for c in full if len(norm(c.get('name'))) == m]\n    if dd:\n        keep = []\n        for c in cand:\n            n = str(c.get('number') or '').replace(' ', '')\n            if len(dd) == 4:\n                if c.get('last4') == dd:\n                    keep.append(c)\n            elif len(dd) == 6:\n                tail = n[-6:]\n                if tail.isdigit():\n                    if tail == dd:\n                        keep.append(c)\n                elif c.get('last4') == dd[-4:]:\n                    keep.append(c)\n            elif len(dd) >= 15:\n                if len(n) == len(dd) and all((not a.isdigit()) or a == b for a, b in zip(n, dd)):\n                    keep.append(c)\n        cand = keep\n    if not toks and not dd:\n        cand = []\n    state = 'retry'\n    fail = False\n    p = q\n    if len(cand) == 1:\n        c = cand[0]\n        if not c.get('main'):\n            p = (c.get('name') or 'Bu') + ' kart\u0131n\u0131z i\u00e7in ekstre borcu sorgulanam\u0131yor. L\u00fctfen ba\u015fka bir kart\u0131n\u0131z\u0131 se\u00e7in. ' + q\n        else:\n            vars['selected_card_number'] = c.get('number')\n            vars['selected_card_last4'] = c.get('last4')\n            vars['selected_card_name'] = c.get('name') or ''\n            state = 'resolved'\n    elif len(cand) > 1:\n        ns = uniq(cand)\n        l4s = set(c.get('last4') for c in cand)\n        if len(ns) > 1:\n            p = join_tr(ns) + ' kartlar\u0131n\u0131z var. Hangisinin borcunu \u00f6\u011frenmek istersiniz?'\n        elif len(l4s) > 1 or len(dd) < 4:\n            p = ns[0] + ' isimli birden fazla kart\u0131n\u0131z var. Kart\u0131n\u0131z\u0131n son d\u00f6rt hanesini s\u00f6yler misiniz?'\n        elif len(dd) == 4:\n            p = 'Son d\u00f6rt hanesi ' + dg(dd) + ' olan birden fazla kart\u0131n\u0131z var. Kart\u0131n\u0131z\u0131n son alt\u0131 hanesini s\u00f6yler misiniz?'\n        elif len(dd) == 6:\n            p = 'Son alt\u0131 hanesi ayn\u0131 olan birden fazla kart\u0131n\u0131z var. Kart numaran\u0131z\u0131 s\u00f6yler misiniz?'\n        else:\n            fail = True\n    else:\n        fail = True\n    if fail:\n        t = int(float(s('sel_tries') or 0)) + 1\n        vars['sel_tries'] = t\n        if intent == 'all_cards' and not toks and not dd:\n            p = 'Bor\u00e7 bilgisini her seferinde tek bir kart i\u00e7in verebiliyorum. ' + q\n        elif toks or dd:\n            p = 'S\u00f6yledi\u011finiz bilgiyle e\u015fle\u015fen bir kart\u0131n\u0131z bulunmuyor. Kartlar\u0131n\u0131z: ' + join_tr(uniq(elig)) + '. Hangisinin borcunu \u00f6\u011frenmek istersiniz?'\n        else:\n            p = q\n        if t >= 3:\n            state = 'tries'\n    vars['select_prompt'] = p\n    vars['card_state'] = state\nexcept Exception:\n    vars['select_prompt'] = s('select_question')\n    vars['card_state'] = 'retry'\nvars['card_name_said'] = ''\nvars['card_digits_said'] = ''\nvars['select_intent'] = 'none'\n"
        },
        "timeout_ms": {
         "type": "number",
