   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "import json, datetime\nMONTHS = ['Ocak', '\u015eubat', 'Mart', 'Nisan', 'May\u0131s', 'Haziran', 'Temmuz', 'A\u011fustos', 'Eyl\u00fcl', 'Ekim', 'Kas\u0131m', 'Aral\u0131k']\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef num(v):\n    try:\n        return float(v)\n    except Exception:\n        return None\ndef pd(t):\n    try:\n        t = str(t or '').strip()\n        if len(t) >= 10 and t[2] == '.' and t[5] == '.':\n            return datetime.date(int(t[6:10]), int(t[3:5]), int(t[0:2]))\n        if len(t) >= 10 and t[4] == '-' and t[7] == '-':\n            return datetime.date(int(t[0:4]), int(t[5:7]), int(t[8:10]))\n    except Exception:\n        pass\n    return None\ndef fd(t):\n    d = pd(t)\n    return '' if d is None else str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)\ndef cop(n):\n    U = ['', 'dir', 'dir', 't\u00fcr', 't\u00fcr', 'tir', 'd\u0131r', 'dir', 'dir', 'dur']\n    T = ['', 'dur', 'dir', 'dur', 't\u0131r', 'dir', 't\u0131r', 'tir', 'dir', 'd\u0131r']\n    if n % 10:\n        return U[n % 10]\n    if n % 100:\n        return T[(n % 100) // 10]\n    if n % 1000:\n        return 'd\u00fcr'\n    return 'dir'\ndef fdc(t):\n    d = pd(t)\n    return '' if d is None else fd(t) + chr(39) + cop(d.year)\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef obj(v):\n    if isinstance(v, (list, dict)):\n        return v\n    if isinstance(v, str) and v.strip()[:1] in ('[', '{'):\n        try:\n            return json.loads(v)\n        except Exception:\n            try:\n                import ast\n                return ast.literal_eval(v)\n            except Exception:\n                return None\n    return None\nCUR = dict(TL=('T\u00fcrk Liras\u0131', 'lira', 'kuru\u015f'), USD=('Dolar', 'Dolar', 'sent'), EUR=('Euro', 'Euro', 'sent'), GBP=('\u0130ngiliz Sterlini', '\u0130ngiliz Sterlini', 'peni'))\nSUF = dict(TL='d\u0131r', USD='d\u0131r', EUR='dur', GBP='dir')\nSUB = dict(kuru\u015f='tur', sent='tir', peni='dir')\ndef amt(cur, x, end=False):\n    c = int(round(abs(float(x)) * 100))\n    w = c // 100\n    f = c % 100\n    full, main, sub = CUR[cur]\n    if f == 0:\n        return format(w, ',').replace(',', '.') + ' ' + full + (chr(39) + SUF[cur] if end else '')\n    return format(w, ',').replace(',', '.') + ' ' + main + ' ' + str(f) + ' ' + sub + (SUB[sub] if end else '')\ndef join_tr(ns):\n    if len(ns) <= 1:\n        return ''.join(ns)\n    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]\ntry:\n    b = obj(vars.get('balance_raw'))\n    if not isinstance(b, dict):\n        b = None\n    P = 'load_balance_response.data.data.'\n    def bg(path):\n        if b is not None:\n            cur = b\n            for p in path.split('.'):\n                if isinstance(cur, dict) and p in cur:\n                    cur = cur[p]\n                else:\n                    return None\n            return cur\n        return vars.get(P + path)\n    def present(key):\n        if b is not None:\n            return isinstance(b.get(key), dict) and len(b.get(key)) > 0\n        return any(str(k).startswith(P + key + '.') for k in list(vars.keys()))\n    bl4 = str(bg('cardNumberLast4') or '')\n    if bl4 and s('selected_card_last4') and bl4 != s('selected_card_last4'):\n        raise ValueError('card mismatch')\n    today = pd(s('now'))\n    name = s('selected_card_name')\n    ref = 'Sonu ' + dg(s('selected_card_last4')) + ' ile biten ' + (name + ' ' if name else '')\n    st = str(bg('statementDate') or '')\n    lp = str(bg('lastPayDate') or '')\n    nlp = str(bg('nextLastPayDate') or '')\n    nst = str(bg('nextStatementDate') or '')\n    vars['stmt_date_raw'] = st\n    CN = dict(TL='T\u00fcrk Liras\u0131', USD='Dolar', EUR='Euro', GBP='\u0130ngiliz Sterlini')\n    info = []\n    for cur, key in [('TL', 'debtTL'), ('USD', 'debtUSD'), ('EUR', 'debtEUR'), ('GBP', 'debtGBP')]:\n        if not present(key):\n            continue\n        sd = num(bg(key + '.statementDebt')) or 0.0\n        mp = num(bg(key + '.minPayment')) or 0.0\n        rd = num(bg(key + '.remainingDebt'))\n        if rd is None:\n            rd = sd\n        rmp = num(bg(key + '.remainingMinPayment'))\n        if rmp is None:\n            rmp = mp\n        td = num(bg(key + '.totalDebt')) or 0.0\n        info.append(dict(cur=cur, sd=sd, mp=mp, rd=rd, rmp=rmp, td=td, has=rd > 0))\n    debts = [i for i in info if i['has']]\n    tl_total = sum(i['td'] for i in info if i['cur'] == 'TL')\n    dlp = pd(lp)\n    parts = []\n    cut_today = bool(today and pd(nst) == today)\n    if cut_today:\n        parts.append('Hesap kesim tarihiniz bug\u00fcn, ekstreniz saat 00.00 itibar\u0131yla kesilecek.')\n    total_said = False\n    if not debts:\n        kind = 'no_debt'\n        if not fd(st):\n            parts.append(ref + 'kart\u0131n\u0131zda ekstre borcunuz bulunmamaktad\u0131r.')\n        else:\n            parts.append(ref + 'kart\u0131n\u0131z\u0131n ' + fd(st) + ' tarihli ekstresinden borcunuz bulunmamaktad\u0131r.')\n            if tl_total > 0:\n                parts.append('Gelecek d\u00f6nemler dahil toplam borcunuz ' + amt('TL', tl_total, True) + '.')\n                total_said = True\n            due = lp if (dlp and today and dlp >= today) else nlp\n            if fd(due):\n                parts.append('Son \u00f6deme tarihiniz ' + fd(due) + ' olacakt\u0131r.')\n    else:\n        kind = 'debt'\n        first = True\n        for i in debts:\n            c = i['cur']\n            lead = ''\n            if first:\n                lead = ref + 'kart\u0131n\u0131za ait ' + (fd(st) + ' tarihinde kesilen ekstre ' if fd(st) else 'ekstre ')\n                first = False\n            if c == 'TL':\n                if i['rmp'] <= 0:\n                    t = 'T\u00fcrk Liras\u0131 borcunuz ' + amt(c, i['sd']) + ', kalan toplam borcunuz ' + amt(c, i['rd'], True) + '. Minimum \u00f6demenizi yapt\u0131\u011f\u0131n\u0131z i\u00e7in te\u015fekk\u00fcr ederiz.'\n                elif i['rmp'] >= i['mp']:\n                    t = 'T\u00fcrk Liras\u0131 borcunuz ' + amt(c, i['sd']) + ', \u00f6denmesi gereken minimum tutar ' + amt(c, i['mp'], True) + '.'\n                else:\n                    t = 'T\u00fcrk Liras\u0131 borcunuz ' + amt(c, i['sd']) + ', \u00f6denmesi gereken minimum tutar ' + amt(c, i['mp']) + ', kalan toplam borcunuz ' + amt(c, i['rd']) + ', kalan minimum \u00f6deme tutar\u0131n\u0131z ' + amt(c, i['rmp'], True) + '.'\n            else:\n                t = CN[c] + ' borcunuz ' + amt(c, i['sd']) + ', kalan toplam borcunuz ' + amt(c, i['rd']) + ', \u00f6denmesi gereken minimum tutar ' + amt(c, i['mp'], True) + '.'\n            parts.append(lead + t)\n        clear = [CN[i['cur']] for i in info if not i['has']]\n        if clear:\n            parts.append(join_tr(clear) + ' borcunuz bulunmamaktad\u0131r.')\n        ap = num(bg('debtTL.remainAutomaticPaymentAmount')) or 0.0\n        if str(bg('automaticPaymentFlag') or '').upper() == 'Y' and ap > 0 and dlp and today and today > dlp:\n            parts.append('Otomatik \u00f6deme talimat\u0131n\u0131zdan al\u0131nacak kalan tutar ' + amt('TL', ap, True) + '.')\n        if dlp and today and dlp == today:\n            parts.append('Bor\u00e7lar\u0131n\u0131z i\u00e7in son \u00f6deme tarihiniz bug\u00fcnd\u00fcr.')\n        elif dlp and today and dlp < today:\n            parts.append(fd(lp) + ' olan son \u00f6deme tarihiniz ge\u00e7mi\u015ftir.')\n            if tl_total > 0:\n                parts.append('Gelecek d\u00f6nemler dahil toplam T\u00fcrk Liras\u0131 borcunuz ' + amt('TL', tl_total, True) + '.')\n                total_said = True\n        elif dlp:\n            parts.append('Bor\u00e7lar\u0131n\u0131z i\u00e7in son \u00f6deme tarihiniz ' + fdc(lp) + '.')\n    if cut_today and not total_said and tl_total > 0:\n        parts.append('Gelecek d\u00f6nemler dahil toplam T\u00fcrk Liras\u0131 borcunuz ' + amt('TL', tl_total, True) + '.')\n    text = ' '.join(parts)\n    vars['reading_text'] = text\n    vars['reading_kind'] = kind\n    multi = int(float(s('card_count') or 0)) > 1\n    em_ok = s('email_state') == 'ok'\n    if s('week_state') == 'changed':\n        vars['offer_text'] = 'Ekstrenizi kay\u0131tl\u0131 mail adresinize g\u00f6nderebilirim.' if em_ok else 'Ba\u015fka hangi konuda yard\u0131mc\u0131 olabilirim?'\n    else:\n        vars['offer_text'] = 'Hesap kesim tarihinizi de\u011fi\u015ftirebilirim ya da ekstrenizi kay\u0131tl\u0131 mail adresinize g\u00f6nderebilirim.' if em_ok else 'Hesap kesim tarihinizi de\u011fi\u015ftirebilirim.'\n    vars['offer_lead'] = '' if multi else text\n    vars['next_step'] = 'other_card' if multi else ('no_debt_end' if kind == 'no_debt' else 'offer')\nexcept Exception:\n    vars['next_step'] = 'error'\nfor k in ['offer_choice', 'other_card_answer', 'email_answer']:\n    vars[k] = 'none'\nvars['balance_rc'] = ''\nvars['select_prompt'] = s('select_question')\n"
