  "prepare_week": {
   "name": "prepare_week",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "end_week_error",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "import datetime\nMONTHS = ['Ocak', '\u015eubat', 'Mart', 'Nisan', 'May\u0131s', 'Haziran', 'Temmuz', 'A\u011fustos', 'Eyl\u00fcl', 'Ekim', 'Kas\u0131m', 'Aral\u0131k']\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef pd(t):\n    try:\n        t = str(t or '').strip()\n        if len(t) >= 10 and t[2] == '.' and t[5] == '.':\n            return datetime.date(int(t[6:10]), int(t[3:5]), int(t[0:2]))\n    except Exception:\n        pass\n    return None\ndef fd(t):\n    d = pd(t)\n    return '' if d is None else str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef digits(x):\n    return ''.join(ch for ch in str(x or '') if ch.isdigit())\ntry:\n    w = int(float(s('wk_week') or s('load_week_response.data.data.statementWeek')))\n    day = int(float(s('wk_day') or s('load_week_response.data.data.statementDay')))\n    if w < 1 or w > 4:\n        raise ValueError('week')\n    vars['current_week'] = str(w)\n    vars['current_day'] = day\n    name = s('selected_card_name')\n    ref = 'Sonu ' + dg(s('selected_card_last4')) + ' ile biten ' + (name + ' ' if name else '') + 'kart\u0131n\u0131z'\n    rel = s('wk_rel').upper()\n    rn = s('wk_rel_name')\n    rl4 = digits(s('wk_rel_number'))[-4:]\n    rref = ('sonu ' + dg(rl4) + ' ile biten ' if rl4 else '') + (rn + ' ' if rn else '') + 'kart\u0131n\u0131z\u0131n'\n    if rel == 'M':\n        subj = ref + ' ile buna ba\u011fl\u0131 ' + rref\n    elif rel == 'C':\n        subj = ref + ' ile bu kart\u0131n ba\u011fl\u0131 oldu\u011fu ' + rref\n    else:\n        subj = ref + '\u0131n'\n        rel = ''\n    vars['rel_type'] = rel\n    vars['rel_name'] = rn\n    opts = [str(k) + '.' for k in range(1, 5) if k != w]\n    ot = 'Hesap kesim tarihinizi ay\u0131n ' + opts[0] + ', ' + opts[1] + ' ya da ' + opts[2] + ' haftas\u0131na alabilirim. Hangisini tercih edersiniz?'\n    t = subj + ' hesap kesim tarihi her ay\u0131n ' + str(w) + '. haftas\u0131 olarak tan\u0131ml\u0131.'\n    if fd(s('wk_next_stmt')) and fd(s('wk_next_due')):\n        t = t + ' Bir sonraki hesap kesim tarihiniz ' + fd(s('wk_next_stmt')) + ', son \u00f6deme tarihiniz ' + fd(s('wk_next_due')) + '.'\n    vars['week_intro'] = t + ' Hesap kesim tarihinizi y\u0131lda bir kez de\u011fi\u015ftirebilirsiniz. ' + ot\n    vars['week_options_text'] = ot\n    vars['week_ready'] = 'ok'\nexcept Exception:\n    vars['week_ready'] = 'error'\nvars['wanted_week'] = 'none'\nvars['week_answer'] = 'none'\nvars['wk_rc'] = ''\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "week_choose",
