         "default": "import datetime\nMONTHS = ['Ocak', '\u015eubat', 'Mart', 'Nisan', 'May\u0131s', 'Haziran', 'Temmuz', 'A\u011fustos', 'Eyl\u00fcl', 'Ekim', 'Kas\u0131m', 'Aral\u0131k']\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef pd(t):\n    try:\n        t = str(t or '').strip()\n        if len(t) >= 10 and t[2] == '.' and t[5] == '.':\n            return datetime.date(int(t[6:10]), int(t[3:5]), int(t[0:2]))\n    except Exception:\n        pass\n    return None\ndef fd(t):\n    d = pd(t)\n    return '' if d is None else str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)\ndef dg(x):\n    return ' '.join(list(str(x)))\ntry:\n    w = int(float(s('wanted_week')))\n    d1 = fd(s('prev_stmt_raw') or s('week_preview_response.data.data.statementDate'))\n    d2 = fd(s('prev_due_raw') or s('week_preview_response.data.data.statementDueDate'))\n    if not d1 or not d2:\n        raise ValueError('preview')\n    vars['chosen_week'] = str(w)\n    rel = s('rel_type')\n    rn = s('rel_name')\n    t = 'Yeni hesap kesim haftan\u0131z her ay\u0131n ' + str(w) + '. haftas\u0131 olacak. Yeni hesap kesim tarihiniz ' + d1 + ', son \u00f6deme tarihiniz ' + d2 + ' olacak.'\n    if rel == 'M' and rn:\n        t = t + ' Bu de\u011fi\u015fiklik kart\u0131n\u0131za ba\u011fl\u0131 ' + rn + ' kart\u0131n\u0131z\u0131 da etkileyecek.'\n    elif rel == 'C' and rn:\n        t = t + ' Bu de\u011fi\u015fiklik kart\u0131n\u0131z\u0131n ba\u011fl\u0131 oldu\u011fu ' + rn + ' kart\u0131n\u0131z\u0131 da etkileyecek.'\n    vars['week_confirm_text'] = t + ' Onayl\u0131yor musunuz?'\n    name = s('selected_card_name')\n    vars['week_done_text'] = 'Sonu ' + dg(s('selected_card_last4')) + ' ile biten ' + (name + ' ' if name else '') + 'kart\u0131n\u0131z\u0131n hesap kesim haftas\u0131 her ay\u0131n ' + str(w) + '. haftas\u0131 olarak de\u011fi\u015ftirildi. Yeni hesap kesim tarihiniz ' + d1 + ', son \u00f6deme tarihiniz ' + d2 + '.'\n    vars['confirm_ready'] = 'ok'\nexcept Exception:\n    vars['confirm_ready'] = 'error'\nvars['confirm_answer'] = 'none'\nvars['prev_rc'] = ''\nvars['prev_stmt_raw'] = ''\nvars['prev_due_raw'] = ''\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "week_confirm",
     "description": "Preview text ready",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "confirm_ready",
        "operator": "equals",
        "operand": "ok"
       }
      ]
     }
    },
    {
     "target_node": "end_week_error",
     "description": "always: preview unusable",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
  "week_confirm": {
   "name": "week_confirm",
   "node_type": "conversation",
   "on_enter": {
    "type": "tts",
    "text": "{{week_confirm_text}}"
   },
   "tools": [],
   "task_message": "You read the new dates from the preview and asked for approval. The change is made only after a clear 'evet'. If the answer is hedged or unclear ('olur herhalde', 'san\u0131r\u0131m', 'olabilir', 'galiba') or the caller says 'just do it' without a clear yes, say only: 'De\u011fi\u015fikli\u011fi yapabilmem i\u00e7in a\u00e7\u0131k onay\u0131n\u0131z gerekiyor. Onayl\u0131yor musunuz?'. If they ask to repeat, repeat word for word: '{{week_confirm_text}}'. Never say that the change was made, and never give dates other than those in the text above. Do not call any tool.",
   "extraction_schema": [
    {
     "name": "confirm_answer",
     "type": "string",
     "enum_values": [
      "yes",
      "no",
      "unclear",
      "none"
     ],
     "description": "Answer in the caller's LAST message to 'Onayl\u0131yor musunuz?': yes ONLY for a clear explicit yes (evet, evet onayl\u0131yorum, onayl\u0131yorum); no = refuses or does not want the change; unclear = hedged or vague ('olur herhalde', 'san\u0131r\u0131m', 'olabilir', 'galiba', 'tamam herhalde', 'sorma yap' without evet); none = other topic.",
     "min_confidence": 0.8
    }
   ],
   "max_node_turns": 4,
   "max_turn_transition": "end_tries",
   "transitions": [
    {
     "target_node": "week_change_call",
     "description": "Clear yes",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "confirm_answer",
        "operator": "equals",
        "operand": "yes"
       }
      ]
     }
    },
    {
     "target_node": "end_main_menu",
     "description": "No change",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "confirm_answer",
        "operator": "equals",
        "operand": "no"
       }
      ]
     }
    },
    {
     "target_node": "prepare_week",
     "description": "Caller wants a different week",
     "condition": {
      "operator": "matches_intent",
      "description": "The caller wants a different statement week than the one just previewed."
     }
    }
   ]
  },
  "week_change_call": {
   "name": "week_change_call",
   "node_type": "api_request",
   "passthrough": true,
   "passthrough_default_transition": "end_week_error",
   "on_enter": {
