1	{
2	 "openapi": "3.0.3",
3	 "info": {
4	  "title": "Freya Bank voice services: statement and debt (test environment mock)",
5	  "version": "1.0.0",
6	  "description": "Seven POST services under /voice/v1/. Request {data, call}; response {data, result}; success = HTTP 200 and result.returnCode '1'. Error answers carry result only. Dates dd.MM.yyyy strings, amounts JSON numbers. The test environment does not check tokens, headers, call or aiFlow."
7	 },
8	 "servers": [
9	  {
10	   "url": "https://yapmak-bank-mock.winter-mountain-4405.workers.dev"
11	  }
12	 ],
13	 "paths": {
14	  "/voice/v1/cards.list": {
15	   "post": {
16	    "summary": "Cards of the customer the assistant may talk about",
17	    "description": "Only active cards (status A) come back. Two cards can share productName and cardNumberLast4. productName is free text and may be empty.",
18	    "requestBody": {
19	     "required": true,
20	     "content": {
21	      "application/json": {
22	       "schema": {
23	        "type": "object",
24	        "description": "Contract envelope: service fields under data, call metadata under call",
25	        "properties": {
26	         "data": {
27	          "type": "object",
28	          "description": "Service request fields",
29	          "properties": {
30	           "customerNo": {
31	            "type": "string",
32	            "description": "Customer number the phone menu passes with the call; string or number both accepted"
33	           },
34	           "aiFlow": {
35	            "type": "string",
36	            "description": "Use case asking; 'CardOps' for this flow",
37	            "default": "CardOps"
38	           }
39	          },
40	          "required": [
41	           "customerNo",
42	           "aiFlow"
43	          ]
44	         },
45	         "call": {
